from pathlib import Path

from otherlib.parse import parse
from plotkit.rows import split


def load(path: Path) -> list[str]:
    with path.open() as f:
        return parse(f.read())


def lines(path: Path) -> list[str]:
    return split(path.read_text())


def unused(path: Path) -> None:
    path.write_text("never reached")


class Step:
    pass


class Double(Step):
    pass


class Pipeline:
    def __init__(self) -> None:
        self.steps: list[type[Step]] = []

    def add(self, step: type[Step]) -> "Pipeline":
        self.steps.append(step)
        return self


def standard() -> Pipeline:
    return Pipeline().add(Double)
